        return match.group(0).replace('""', '"')

    fields = re.split(r'(,)(?=(?:[^"]*"[^"]*")*[^"]*$)', line)
    unquoted_fields = [re.sub(r'(^")|("$)', '', field) for field in fields]
    cleaned_fields = [re.sub(r'""', replace_doubled_quotes, field) for field in unquoted_fields]

    return cleaned_fields
