import re

def split_fields(line):
    def replace_doubled_quote(match):
        return match.group(0).replace('""', '"')

    # Regular expression to match quoted fields and unquoted fields
    pattern = re.compile(r'"([^"]*)"|([^,]+)')

    # Find all matches in the line
    matches = pattern.findall(line)

    # Process each match
    result = []
    for match in matches:
        # If it's a quoted field, remove the quotes and replace doubled quotes
        if match[0]:
            result.append(replace_doubled_quote(match[0]))
        # If it's an unquoted field, keep it as is
        else:
            result.append(match[1])

    return result
