def split_fields(line):
    def nextch():
        nonlocal pos, ch, line
        pos += 1
        if pos < len(line):
            ch = line[pos]
        else:
            ch = None

    def chmatch(expected):
        nonlocal ch
        if ch == expected:
            nextch()
            return True
        return False

    result = []
    pos, ch = 0, None
    nextch()
    while ch is not None:
        if not chmatch('"'):
            field = ""
            while ch is not None and not chmatch(','):
                field += ch
                nextch()
            result.append(field)
            if chmatch(','):
                continue
        else:
            field = ""
            while ch is not None and not (chmatch('"') and chmatch('"')):
                if chmatch('"') and chmatch('"'):
                    field += '"'
                elif ch is not None:
                    field += ch
                    nextch()
            nextch()
            result.append(field)
    return result
