import re

def split_fields(line):
    field_pattern = re.compile(r'"([^"]*?)"|([^,]+)')
    fields = []
    i = 0
    while i < len(line):
        if line[i] == '"':
            match = field_pattern.match(line, i)
            if match:
                field = match.group(1).replace('""', '"')
                fields.append(field)
                i = match.end()
        else:
            match = field_pattern.match(line, i)
            if match:
                fields.append(match.group(2))
                i = match.end()
            else:
                break
    return fields
